def render_text(open_tag: str, new: str) -> str:
    """Build <text> inner XML. Multi-line becomes tspans with x+dy breaks (px units)."""
    parts = new.split("\n")
    xm = re.search(r'\bx="([^"]+)"', open_tag)
    x = xm.group(1) if xm else None
    fsm = re.search(r'font-size="([^"]+)"', open_tag)
    try:
        font_px = float(fsm.group(1)) if fsm else 32.0
    except ValueError:
        font_px = 32.0
    line_dy = round(font_px * 1.3, 1)
    if len(parts) == 1:
        return open_tag + f"<tspan>{parts[0]}</tspan></text>"
    inner = []
    for i, p in enumerate(parts):
        if x is not None:
            dy = "0" if i == 0 else str(line_dy)
            inner.append(f'<tspan x="{x}" dy="{dy}">{p}</tspan>')
        else:
            inner.append(f"<tspan>{p}</tspan>")
    return open_tag + "".join(inner) + "</text>"

